 const panel=document.createElement('div');panel.id='yp-apply-review';panel.className='yp-steps yp-rent';panel.dataset.step=step;panel.dataset.ypId=id;panel.setAttribute('role','dialog');panel.setAttribute('aria-labelledby','yp-review-title');const card=document.createElement('div');card.className='card yp-listing yp-step';const shut=()=>{clearInterval(ypAppTimer);panel.remove();};
