 const text=(t,cls)=>{const p=document.createElement('p');if(cls)p.className=cls;p.textContent=t;card.appendChild(p);return p;};const btn=(label,cls,fn,bid)=>{const b=document.createElement('button');b.type='button';b.className=cls;b.textContent=label;if(bid)b.id=bid;b.addEventListener('click',fn);card.appendChild(b);return b;};const M=ypMoneyText;const pic=ypRentPicture(r.weeklyRent,null);
 const current=(ypReadStock().rentals||[]).find(x=>x.status==='active'&&x.bondCharged&&x.id!==id)||null;
 const withdraw=()=>{const all=ypReadStock();const x=(all.rentals||[]).find(y=>y.id===id);if(x&&(x.status==='application-pending'||x.status==='approved')){x.status='cancelled';x.notified='cancelled';delete x.approveGameMs;delete x.approveAt;const c=ypReadClock();const ev=ypHistoryEvent(id,'cancelled',ypRentMs(x,c),'You withdrew your application',c.wall);ypWriteStock(all);if(ev)ypRecordHistory([ev]);if(typeof save==='function')save();}shut();ypOpenRentalDetail(id);};
