  card.appendChild(ypFlow([{label:'Weekly rent',hint:'Paid each game week',value:M(pic.rent),id:'yp-rent-wk'},{label:'Four-week bond',hint:'Held by the RTA, back when you leave',value:M(pic.bond),id:'yp-rent-bond'},{label:'Rent in advance',hint:'Two weeks, your first two weeks',value:M(pic.advance),id:'yp-rent-adv'},{label:'To move in',hint:'Paid when you sign the lease',value:M(pic.upfront),id:'yp-rent-upfront'},{label:'Application Date',hint:'Game date',value:typeof ypRealDateLabel==='function'?ypRealDateLabel(Date.now()):''},{label:'Tenancy Length',hint:'You choose when you sign',value:'6 or 12 months'}]));
  if(current)text('You rent '+ypRentName(current)+' now. If you sign this lease, that lease ends and its '+M(current.bondPaid||0)+' bond comes back to you.','yp-limit');
  const v=text(c.verdict,'yp-status');v.id='yp-rent-verdict';
  text('Next, the property manager checks your ID, references and income. It takes about 1 game hour and the bell tells you the answer. Applying does not charge you.');
  const err=text(note||'','yp-status');err.id='yp-rent-error';let sent=false;
  btn('Send application','hwb',()=>{if(sent)return;sent=true;const clock=ypReadClock();const res=ypApplySample(ypReadStock(),id,clock);if(!res.ok){sent=false;err.textContent=res.reason==='already'?'This rental already has an application. Nothing was charged.':'This application could not be sent. Nothing was charged.';return;}const rr=res.store.rentals.find(x=>x.id===id);if(rr){delete rr.callSeen;delete rr.keysSeen;delete rr.declineWhy;delete rr.moveStep;delete rr.evMs;}ypWriteStock(res.store);ypRecordHistory(res.events);if(typeof save==='function')save();ypOpenRentStep(id,'review');},'yp-rent-send');
