function ypMountListSearch(){const host=document.getElementById('map');if(!host)return;if(!document.getElementById('yp-list-search')){const b=document.createElement('button');b.type='button';b.id='yp-list-search';b.setAttribute('aria-label','Search a town or suburb');const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('fill','none');path.setAttribute('stroke','currentColor');path.setAttribute('stroke-width','2.4');path.setAttribute('stroke-linecap','round');path.setAttribute('d','M10.5 4a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13zM15.5 15.5 20 20');svg.appendChild(path);const text=document.createElement('span');text.id='yp-list-search-text';const change=document.createElement('span');change.id='yp-list-search-change';change.textContent='Change';b.append(svg,text,change);b.addEventListener('click',()=>{ypShowWherePopup();});host.appendChild(b);}ypSyncListSearch();setTimeout(ypLoadLocalPlaces,0);}
