/* Home feed: one running event stream, newest first by game time. Real player listings arrive through ypFeedEvent({kind:'listed', ...}). Sample seed events, seeded days, and sponsored ads are not generated and are purged from yp.homeFeed.v1 on read. */
const YP_FEED_KEY='yp.homeFeed.v1';
const YP_FEED_TYPES={home:'Residential',trade:'Commercial',other:'Other building'};
let ypFeedManifest=null;const ypFeedChunks=new Map();
function ypFeedVisible(e){return !!(e&&e.kind==='listed'&&!e.sample);}
function ypFeedRead(){try{const o=JSON.parse(localStorage.getItem(YP_FEED_KEY)||'null');if(o&&o.version===1&&Array.isArray(o.events)){const events=o.events.filter(e=>e&&!e.sample&&!(e.key&&String(e.key).indexOf('sample|')===0));const dirty=events.length!==o.events.length||(Array.isArray(o.seeded)&&o.seeded.length)||('seeded' in o);o.events=events;if('seeded' in o)delete o.seeded;if(dirty)ypFeedWrite(o);return o;}}catch(e){}return {version:1,events:[]};}
function ypFeedWrite(o){o.events.sort((a,b)=>b.gameMs-a.gameMs);o.events.length=Math.min(o.events.length,200);try{localStorage.setItem(YP_FEED_KEY,JSON.stringify({version:1,events:o.events}));}catch(e){}}
function ypFeedNow(){const c=ypReadClock();return {ms:ypGameMs(c),dayMs:c.weekMs/7};}
/* Add one real event and show it at once. ev: {kind:'listed'|'sold', id, price, tone, area, lon, lat, gameMs?, by?} */
function ypFeedEvent(ev){if(!ev||!ev.id||ev.sample||(ev.kind!=='listed'&&ev.kind!=='sold'))return;const o=ypFeedRead();const gameMs=Number.isFinite(+ev.gameMs)?+ev.gameMs:ypFeedNow().ms;const key=ev.key||ev.kind+'|'+ev.id+'|'+gameMs;if(o.events.some(e=>e.key===key))return;const rec={...ev,key,gameMs};delete rec.sample;o.events.push(rec);ypFeedWrite(o);const feed=document.getElementById('yp-feed');if(feed)feed.dataset.key='';ypSyncFeed();}
window.ypFeedEvent=ypFeedEvent;
async function ypFeedChunk(id){if(!ypFeedChunks.has(id))ypFeedChunks.set(id,await (await fetch('data/chunks/'+id+'.json?v=prices1')).json());return ypFeedChunks.get(id);}
function ypFeedIcon(tone){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',{home:'M12 3 2 12h3v8h5v-5h4v5h5v-8h3z',trade:'M3 4h18l1 5c0 1.7-1.3 3-3 3s-3-1.3-3-3c0 1.7-1.3 3-3 3s-3-1.3-3-3c0 1.7-1.3 3-3 3s-3-1.3-3-3l1-5zm2 9.5V20h14v-6.5c-.6.3-1.3.5-2 .5v4H7v-4c-.7 0-1.4-.2-2-.5z',other:'M4 21V5l8-3 8 3v16h-6v-5h-4v5zm4-13v2h2V8zm6 0v2h2V8zm-6 4v2h2v-2zm6 0v2h2v-2z'}[YP_FEED_TYPES[tone]?tone:'other']);svg.appendChild(path);return svg;}
function ypFeedRow(ev){const row=document.createElement('div');row.className='yp-feed-row';row.setAttribute('role','button');row.tabIndex=0;row.dataset.id=ev.id;const pic=document.createElement('span');pic.className='yp-feed-pic';const badge=document.createElement('span');badge.className='yp-feed-badge yp-feed-badge--'+(ev.kind==='sold'?'sold':'sale');badge.textContent=ev.kind==='sold'?'SOLD':'FOR SALE';pic.append(ypFeedIcon(ev.tone),badge);const info=document.createElement('span');info.className='yp-feed-info';const when=document.createElement('span');when.className='yp-feed-tag';when.textContent=ypEventClockLabel({gameMs:ev.gameMs});const price=document.createElement('span');price.className='yp-feed-price';price.textContent=fmt(ev.price);const meta=document.createElement('span');meta.className='yp-feed-meta';meta.textContent=[YP_FEED_TYPES[ev.tone]||'Building',ev.area?Number(ev.area).toLocaleString()+' m²':'',ev.by?'Bought by '+ev.by:''].filter(Boolean).join(' · ');const id=document.createElement('span');id.className='yp-feed-id';id.appendChild(ypPropertyLink(ev.id,{target:{lon:ev.lon,lat:ev.lat}}));info.append(when,price,meta,id);row.append(pic,info);row.addEventListener('click',()=>ypGoToProperty(ev));row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();ypGoToProperty(ev);}});return row;}
function ypRenderFeed(){const now=ypFeedNow().ms;const events=ypFeedRead().events.filter(e=>e.gameMs<=now&&ypFeedVisible(e)).slice(0,60);let feed=document.getElementById('yp-feed');const key=events.map(e=>e.key).join(',')||'empty';if(feed&&feed.dataset.key===key)return;if(!feed){feed=document.createElement('div');feed.id='yp-feed';feed.setAttribute('aria-label','Home feed');document.body.appendChild(feed);}feed.dataset.key=key;const card=document.createElement('section');card.className='yp-feed-card';if(events.length)events.forEach(ev=>card.appendChild(ypFeedRow(ev)));else{const note=document.createElement('p');note.className='yp-feed-meta';note.textContent='No properties listed yet.';card.appendChild(note);}feed.replaceChildren(card);}
function ypSyncFeed(){const show=document.documentElement.classList.contains('yp-home')&&!document.getElementById('flow');if(show)ypRenderFeed();const feed=document.getElementById('yp-feed');if(feed)feed.hidden=!show||!feed.childElementCount;}
(function(){let t=0;const run=()=>{clearTimeout(t);t=setTimeout(()=>{ypSyncNav();ypSyncFeed();},60);};const go=()=>{new MutationObserver(run).observe(document.body,{childList:true,subtree:false,attributes:true,attributeFilter:['class']});new MutationObserver(run).observe(document.documentElement,{attributes:true,attributeFilter:['class']});document.addEventListener('click',run,true);setInterval(run,5000);run();};if(document.body)go();else document.addEventListener('DOMContentLoaded',go);})();

function ypBankCounts(){const box=document.getElementById('bankbox');if(!box||box.querySelector('#yp-bank-counts')||typeof bank!=='function')return;const b=bank(),B=ypWeekBudget(),f=n=>typeof fmt==='function'?fmt(n):ypMoneyText(n),ar=b.ar,n=BANK.termY*12;const rows=[{heading:'What the bank counts'}];if(b.rentMo)rows.push(B.lease&&B.housing==='rent'?{label:'Rent you pay',hint:f(B.lease.rent)+' a week',propertyId:B.lease.id,value:f(b.rentMo)+'/mo'}:{label:B.housing==='family'?'Board you pay':'Board you pay',hint:'Each month',value:f(b.rentMo)+'/mo'});Object.values(ypReadBuys().buys).filter(x=>(x.status==='owned'||x.status==='contract')&&+x.loan>0).forEach(x=>rows.push({label:x.status==='owned'?'Home loan':'Loan at settlement',hint:'Balance '+f(x.loan)+', tested at '+(ar*100).toFixed(2)+'%',propertyId:x.id,value:f(x.loan/annuity(ar,n))+'/mo'}));try{let other=0;for(const[,p]of allProps())other+=+p.loan||0;if(other>0)rows.push({label:'Other game loans',hint:'Balance '+f(other)+', tested at '+(ar*100).toFixed(2)+'%',value:f(other/annuity(ar,n))+'/mo'});}catch(e){}if(rows.length===1)rows.push({label:'Rent and loans',hint:'You have none yet',value:f(0)});const wrap=document.createElement('div');wrap.id='yp-bank-counts';wrap.appendChild(ypFlow(rows));const top=box.querySelector('#borrowtop');(top||box).insertAdjacentElement(top?'afterend':'afterbegin',wrap);}
(function(){function hook(){const ui=ypGameUI&&ypGameUI();if(!ui||!ui.lenders||ui.lenders.__ypFin)return !!(ui&&ui.lenders);const o=ui.lenders;ui.lenders=function(){const r=o.apply(this,arguments);try{ypBankCounts();}catch(e){}return r;};ui.lenders.__ypFin=1;return true;}if(!hook()){let k=0;const t=setInterval(()=>{if(hook()||++k>40)clearInterval(t);},250);}})();
